def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    sorted_nums = sorted(set(nums))
    result = []
    i = 0
    n = len(sorted_nums)

    while i < n:
        start = sorted_nums[i]
        end = start
        while i + 1 < n and sorted_nums[i + 1] == end + 1:
            i += 1
            end = sorted_nums[i]

        if start == end:
            result.append(str(start))
        elif end == start + 1:
            result.append(str(start))
            result.append(str(end))
        else:
            result.append(f"{start}..{end}")

        i += 1

    return ",".join(result)
